import { Column, CreateDateColumn, Entity, Index, PrimaryColumn, UpdateDateColumn } from "typeorm";

/**
 * A user-placed point of interest.
 *
 * Column types are chosen to mean the same thing on every dialect: TypeORM maps
 * `uuid` to a native uuid on Postgres and to `varchar` on sqlite, and the date
 * columns to `timestamp` / `datetime` respectively. `double precision` is
 * accepted verbatim by both.
 */
@Entity({ name: "pois" })
@Index("pois_lat_lon", ["lat", "lon"])
export class PoiEntity {
  /**
   * Generated by the application rather than the database. A
   * `@PrimaryGeneratedColumn("uuid")` would lean on a column default that only
   * some engines have (Postgres needs `gen_random_uuid()`, sqlite has nothing),
   * which is exactly the kind of difference this layer is meant to hide.
   */
  @PrimaryColumn({ type: "uuid" })
  id!: string;

  @Column({ type: "varchar", length: 80 })
  name!: string;

  /** a single emoji, rendered as the map marker */
  @Column({ type: "varchar", length: 16 })
  emoji!: string;

  @Column({ type: "double precision" })
  lat!: number;

  @Column({ type: "double precision" })
  lon!: number;

  @CreateDateColumn({ name: "created_at" })
  createdAt!: Date;

  @UpdateDateColumn({ name: "updated_at" })
  updatedAt!: Date;
}
